def transform(grid):
    from collections import Counter
    if not grid:
        return grid

    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    h, w = len(grid), len(grid[0])
    oh, ow = h // 2, w // 2

    res = [[0] * ow for _ in range(oh)]

    for r in range(oh):
        for c in range(ow):
            v_tl = grid[r][c]
            v_tr = grid[r][c + w//2]
            v_bl = grid[r + h//2][c]
            v_br = grid[r + h//2][c + w//2]

            # Priority based on value: higher threshold values win (3 > 1 > 0)
            # But also respecting position order when values are equal
            cand = []
            if v_tr != bg:
                cand.append((0, v_tr, 'TR'))
            if v_br != bg:
                cand.append((1, v_br, 'BR'))
            if v_bl != bg:
                cand.append((2, v_bl, 'BL'))
            if v_tl != bg:
                cand.append((3, v_tl, 'TL'))

            if not cand:
                res[r][c] = bg
            else:
                # Sort by priority, then by value descending
                cand.sort(key=lambda x: (x[0], -x[1]))
                res[r][c] = cand[0][1]

    return res
